import { readFileSync, readdirSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/errors-malformed';
const BIN = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).filter((f) => f.endsWith('.txt')).sort();
const tally = new Map();
const ok = [];
const argparseFail = [];
for (const f of files) {
  const a = readFileSync(DIR + '/' + f, 'utf8');
  const r = spawnSync(BIN, ['--a', a], { encoding: 'utf8', maxBuffer: 1 << 24 });
  const err = (r.stderr || '').trim().split('\n').filter(Boolean);
  const kind =
    r.status === 0
      ? 'OK(parsed)'
      : /usage:|expected one argument|unrecognized arguments/.test(r.stderr)
      ? 'ARGPARSE'
      : (err[err.length - 1] || 'rc' + r.status).slice(0, 60);
  tally.set(kind, (tally.get(kind) || 0) + 1);
  if (r.status === 0) ok.push(f + '  ' + JSON.stringify(a).slice(0, 60));
  if (kind === 'ARGPARSE') argparseFail.push(f + '  ' + JSON.stringify(a).slice(0, 60));
}
console.log('total', files.length);
console.log('--- error-kind tally ---');
for (const [k, v] of [...tally].sort((x, y) => y[1] - x[1])) console.log(String(v).padStart(4), k);
console.log('--- ARGPARSE failures (' + argparseFail.length + ') ---');
argparseFail.forEach((s) => console.log(' ', s));
console.log('--- parsed successfully (' + ok.length + ') ---');
ok.forEach((s) => console.log(' ', s));

import { spawnSync } from 'node:child_process';
const BIN = '/workspace/dataset/test14_executable';
const cands = [
  'x: ',
  'x: ',
  'x: ab',
  'x: !!binary "aGVsbG8"',
  'x: !!binary "a==="',
  'x: !!binary "$$$$"',
  'x: !!binary "ab=c"',
  'x: !!int "0b12"',
  'x: !!int "0o8"',
  'x: !!bool "on off"',
  'x: !!binary "é"',
];
for (const a of cands) {
  const r = spawnSync(BIN, ['--a', a], { encoding: 'utf8' });
  const lines = (r.stderr || '').trim().split('\n').filter(Boolean);
  const cls = lines.find((l) => /^\w[\w.]*(Error|Exception)/.test(l)) || lines[lines.length - 1] || '';
  console.log(r.status, JSON.stringify(a), '=>', JSON.stringify((r.stdout || '').slice(0, 40)), '|', cls.slice(0, 80));
}

